package com.carddemo.account;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * CardDemo Account Enquiry Service
 *
 * <p>Replaces COACCT01.cbl: a CICS-hosted IBM MQ listener that received account
 * enquiry requests ({@code INQA} function code + account ID) and returned account
 * details from the ACCTDAT VSAM file.
 *
 * <p>This service exposes the same logic as a REST API backed by an H2 (embedded)
 * or PostgreSQL database, using Spring Data JPA instead of EXEC CICS READ.
 */
@SpringBootApplication
public class AccountEnquiryApplication {

    public static void main(String[] args) {
        SpringApplication.run(AccountEnquiryApplication.class, args);
    }
}

package com.carddemo.account.web;

import com.carddemo.account.service.AccountEnquiryService;
import com.carddemo.account.web.dto.AccountEnquiryRequest;
import com.carddemo.account.web.dto.AccountEnquiryResponse;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

/**
 * REST entry point replacing the IBM MQ interface of COACCT01.cbl.
 *
 * <h2>Interface mapping</h2>
 * <table border="1">
 *   <tr><th>COBOL</th><th>REST</th></tr>
 *   <tr><td>MQ GET from input queue</td><td>POST /api/accounts/enquiry (request body)</td></tr>
 *   <tr><td>MQ PUT to CARD.DEMO.REPLY.ACCT</td><td>HTTP 200 with JSON body</td></tr>
 *   <tr><td>MQ PUT to CARD.DEMO.ERROR</td><td>HTTP 200 with JSON {@code error} field, or HTTP 500</td></tr>
 *   <tr><td>PERFORM 8000-TERMINATION</td><td>HTTP 500 (unhandled exception)</td></tr>
 * </table>
 *
 * <p>Note: the COBOL program uses a fire-and-forget MQ pattern — the caller's
 * correlation ID is echoed back in the reply.  In this REST mapping the response
 * is returned synchronously, which is the natural HTTP equivalent.
 */
@RestController
@RequestMapping("/api/accounts")
public class AccountController {

    private final AccountEnquiryService enquiryService;

    public AccountController(AccountEnquiryService enquiryService) {
        this.enquiryService = enquiryService;
    }

    /**
     * Account enquiry — replaces the COACCT01 MQ request/reply cycle.
     *
     * <p>HTTP 200 is returned in all handled cases (found, not-found, invalid function).
     * This mirrors the COBOL behaviour: even error messages are placed on the reply
     * queue with a normal MQ completion code.
     *
     * @param request validated request DTO
     * @return enquiry response — check {@code error} field for business-level errors
     */
    @PostMapping("/enquiry")
    public ResponseEntity<AccountEnquiryResponse> enquire(
            @RequestBody @Valid AccountEnquiryRequest request) {

        AccountEnquiryResponse response = enquiryService.enquire(request);
        return ResponseEntity.ok(response);
    }

    /**
     * Convenience GET endpoint for quick account lookup by ID.
     * Not in the original COACCT01 — added for REST usability.
     */
    @GetMapping("/{accountId}")
    public ResponseEntity<AccountEnquiryResponse> getById(
            @PathVariable Long accountId) {

        AccountEnquiryRequest request = new AccountEnquiryRequest("INQA", accountId);
        AccountEnquiryResponse response = enquiryService.enquire(request);
        return ResponseEntity.ok(response);
    }
}

package com.carddemo.account.service;

import com.carddemo.account.domain.Account;
import com.carddemo.account.repository.AccountRepository;
import com.carddemo.account.web.dto.AccountEnquiryRequest;
import com.carddemo.account.web.dto.AccountEnquiryResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;

/**
 * Implements the core account enquiry logic from COACCT01.cbl paragraph
 * {@code 4000-PROCESS-REQUEST-REPLY}.
 *
 * <h2>COBOL to Java mapping</h2>
 * <pre>
 * COBOL (COACCT01.cbl:4000-PROCESS-REQUEST-REPLY)       Java
 * ─────────────────────────────────────────────       ──────────────────────────────
 * IF WS-FUNC = 'INQA' AND WS-KEY > ZEROES          → functionCode.equals("INQA")
 *   EXEC CICS READ DATASET('ACCTDAT')               → accountRepository.findById(id)
 *     RIDFLD(WS-CARD-RID-ACCT-ID-X)
 *     RESP(WS-RESP-CD)
 *   EVALUATE WS-RESP-CD
 *     WHEN DFHRESP(NORMAL)  → build WS-ACCT-RESPONSE  → AccountEnquiryResponse.success(…)
 *     WHEN DFHRESP(NOTFND)  → STRING 'INVALID…'       → AccountEnquiryResponse.error(…)
 *     WHEN OTHER            → PERFORM 9000-ERROR       → throw RuntimeException (→ 500)
 * ELSE                      → STRING 'INVALID…'       → AccountEnquiryResponse.error(…)
 * END-IF
 * </pre>
 */
@Service
@Transactional(readOnly = true)
public class AccountEnquiryService {

    private static final Logger log =
            LoggerFactory.getLogger(AccountEnquiryService.class);

    /** Only supported function code — mirrors WS-FUNC = 'INQA' */
    static final String FUNC_INQA = "INQA";

    private final AccountRepository accountRepository;

    public AccountEnquiryService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    /**
     * Processes one account enquiry request.
     *
     * <p>Mirrors the COBOL control flow in {@code 4000-PROCESS-REQUEST-REPLY}:
     * <ol>
     *   <li>Validate function code and key (replaces {@code IF WS-FUNC = 'INQA' AND WS-KEY > ZEROES}).</li>
     *   <li>Read account by ID (replaces {@code EXEC CICS READ DATASET('ACCTDAT')}).</li>
     *   <li>Map found account to response (replaces the series of {@code MOVE ACCT-* TO WS-ACCT-*}).</li>
     *   <li>Return error response if not found (replaces {@code DFHRESP(NOTFND)} branch).</li>
     * </ol>
     *
     * @param request validated enquiry request
     * @return success response with account fields, or error response
     */
    public AccountEnquiryResponse enquire(AccountEnquiryRequest request) {

        // Guard: WS-FUNC = 'INQA' AND WS-KEY > ZEROES (COACCT01:4000)
        if (!FUNC_INQA.equals(request.functionCode())) {
            String msg = String.format(
                    "INVALID REQUEST PARAMETERS ACCT ID : %d FUNCTION : %s",
                    request.accountId(), request.functionCode());
            log.warn(msg);
            return AccountEnquiryResponse.error(msg);
        }

        log.debug("Account enquiry: id={}", request.accountId());

        // EXEC CICS READ DATASET('ACCTDAT') RIDFLD(WS-CARD-RID-ACCT-ID-X)
        Optional<Account> found = accountRepository.findById(request.accountId());

        // EVALUATE WS-RESP-CD
        //   WHEN DFHRESP(NOTFND)
        if (found.isEmpty()) {
            String msg = String.format(
                    "INVALID REQUEST PARAMETERS ACCT ID : %d",
                    request.accountId());
            log.debug("Account not found: {}", request.accountId());
            return AccountEnquiryResponse.error(msg);
        }

        // WHEN DFHRESP(NORMAL) → MOVE ACCT-* TO WS-ACCT-*
        Account acct = found.get();
        log.debug("Account found: id={} status={} bal={}",
                acct.getAcctId(), acct.getActiveStatus(), acct.getCurrBal());

        return AccountEnquiryResponse.success(
                acct.getAcctId(),
                acct.getActiveStatus(),
                acct.getCurrBal(),
                acct.getCreditLimit(),
                acct.getCashCreditLimit(),
                acct.getOpenDate(),
                acct.getExpirationDate(),
                acct.getReissueDate(),
                acct.getCurrCycCredit(),
                acct.getCurrCycDebit(),
                acct.getGroupId()
        );
    }
}

package com.carddemo.account.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.math.BigDecimal;

/**
 * JPA entity that replaces the VSAM ACCTDAT file.
 *
 * <p>Field layout follows copybook {@code app/cpy/CVACT01Y.cpy} (ACCOUNT-RECORD, 300 bytes).
 * All financial fields are {@link BigDecimal} with scale 2 — replacing COBOL
 * {@code PIC S9(10)V99} (including COMP-3 variants).
 * Date fields are stored as {@code String} matching the COBOL {@code PIC X(10)}
 * format {@code YYYY-MM-DD}.
 */
@Entity
@Table(name = "accounts")
public class Account {

    /** ACCT-ID PIC 9(11) — primary key */
    @Id
    @Column(name = "acct_id")
    private Long acctId;

    /** ACCT-ACTIVE-STATUS PIC X(01) — 'Y' or 'N' */
    @Column(name = "active_status", length = 1, nullable = false)
    private String activeStatus;

    /** ACCT-CURR-BAL PIC S9(10)V99 */
    @Column(name = "curr_bal", precision = 12, scale = 2, nullable = false)
    private BigDecimal currBal;

    /** ACCT-CREDIT-LIMIT PIC S9(10)V99 */
    @Column(name = "credit_limit", precision = 12, scale = 2, nullable = false)
    private BigDecimal creditLimit;

    /** ACCT-CASH-CREDIT-LIMIT PIC S9(10)V99 */
    @Column(name = "cash_credit_limit", precision = 12, scale = 2, nullable = false)
    private BigDecimal cashCreditLimit;

    /** ACCT-OPEN-DATE PIC X(10) format YYYY-MM-DD */
    @Column(name = "open_date", length = 10)
    private String openDate;

    /**
     * ACCT-EXPIRAION-DATE PIC X(10) format YYYY-MM-DD
     * <p>Note: spelling "EXPIRAION" (missing 'T') is retained from the COBOL source
     * to aid traceability ({@code app/cpy/CVACT01Y.cpy}).
     */
    @Column(name = "expiration_date", length = 10)
    private String expirationDate;

    /** ACCT-REISSUE-DATE PIC X(10) format YYYY-MM-DD */
    @Column(name = "reissue_date", length = 10)
    private String reissueDate;

    /** ACCT-CURR-CYC-CREDIT PIC S9(10)V99 */
    @Column(name = "curr_cyc_credit", precision = 12, scale = 2, nullable = false)
    private BigDecimal currCycCredit;

    /** ACCT-CURR-CYC-DEBIT PIC S9(10)V99 */
    @Column(name = "curr_cyc_debit", precision = 12, scale = 2, nullable = false)
    private BigDecimal currCycDebit;

    /** ACCT-ADDR-ZIP PIC X(10) */
    @Column(name = "addr_zip", length = 10)
    private String addrZip;

    /** ACCT-GROUP-ID PIC X(10) */
    @Column(name = "group_id", length = 10)
    private String groupId;

    // ── Getters ──────────────────────────────────────────────────────

    public Long getAcctId()              { return acctId; }
    public String getActiveStatus()      { return activeStatus; }
    public BigDecimal getCurrBal()       { return currBal; }
    public BigDecimal getCreditLimit()   { return creditLimit; }
    public BigDecimal getCashCreditLimit() { return cashCreditLimit; }
    public String getOpenDate()          { return openDate; }
    public String getExpirationDate()    { return expirationDate; }
    public String getReissueDate()       { return reissueDate; }
    public BigDecimal getCurrCycCredit() { return currCycCredit; }
    public BigDecimal getCurrCycDebit()  { return currCycDebit; }
    public String getAddrZip()           { return addrZip; }
    public String getGroupId()           { return groupId; }

    // ── Setters (needed by JPA and tests) ────────────────────────────

    public void setAcctId(Long acctId)                         { this.acctId = acctId; }
    public void setActiveStatus(String activeStatus)           { this.activeStatus = activeStatus; }
    public void setCurrBal(BigDecimal currBal)                 { this.currBal = currBal; }
    public void setCreditLimit(BigDecimal creditLimit)         { this.creditLimit = creditLimit; }
    public void setCashCreditLimit(BigDecimal cashCreditLimit) { this.cashCreditLimit = cashCreditLimit; }
    public void setOpenDate(String openDate)                   { this.openDate = openDate; }
    public void setExpirationDate(String expirationDate)       { this.expirationDate = expirationDate; }
    public void setReissueDate(String reissueDate)             { this.reissueDate = reissueDate; }
    public void setCurrCycCredit(BigDecimal currCycCredit)     { this.currCycCredit = currCycCredit; }
    public void setCurrCycDebit(BigDecimal currCycDebit)       { this.currCycDebit = currCycDebit; }
    public void setAddrZip(String addrZip)                     { this.addrZip = addrZip; }
    public void setGroupId(String groupId)                     { this.groupId = groupId; }
}

package com.carddemo.account.repository;

import com.carddemo.account.domain.Account;
import org.springframework.data.jpa.repository.JpaRepository;

/**
 * Replaces the EXEC CICS READ DATASET('ACCTDAT') RIDFLD(WS-CARD-RID-ACCT-ID-X)
 * call in COACCT01.cbl (paragraph 4000-PROCESS-REQUEST-REPLY).
 *
 * <ul>
 *   <li>{@link #findById(Long)} — random-key read; empty Optional = DFHRESP(NOTFND)</li>
 *   <li>{@link #existsById(Long)} — key existence check without fetching data</li>
 * </ul>
 */
public interface AccountRepository extends JpaRepository<Account, Long> {
}

package com.carddemo.account.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * Replaces the MQ request message layout from COACCT01.cbl:
 * <pre>
 *   01 REQUEST-MSG-COPY.
 *      10 WS-FUNC   PIC X(04) VALUE SPACES.   ← functionCode
 *      10 WS-KEY    PIC 9(11) VALUE ZEROES.   ← accountId
 *      10 WS-FILLER PIC X(985).
 * </pre>
 *
 * <p>The COBOL program validates {@code WS-FUNC = 'INQA'} and {@code WS-KEY > ZEROES}
 * before performing the account lookup.  The same guard is implemented in
 * {@link com.carddemo.account.service.AccountEnquiryService#enquire}.
 *
 * @param functionCode must be "INQA" to trigger an account lookup
 * @param accountId    ACCT-ID PIC 9(11); must be positive
 */
public record AccountEnquiryRequest(

        @NotBlank
        String functionCode,

        @NotNull @Positive
        Long accountId
) {}

package com.carddemo.account.exception;

import com.carddemo.account.web.dto.AccountEnquiryResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;

import java.util.stream.Collectors;

/**
 * Maps validation and unexpected errors to HTTP responses.
 *
 * <p>COBOL equivalent: PERFORM 9000-ERROR + PERFORM 8000-TERMINATION
 * (COACCT01.cbl — terminates program and puts error on CARD.DEMO.ERROR queue).
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log =
            LoggerFactory.getLogger(GlobalExceptionHandler.class);

    /**
     * Bean Validation failures (e.g. missing functionCode, accountId ≤ 0).
     * Returns HTTP 400 with a descriptive error message.
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<AccountEnquiryResponse> handleValidation(
            MethodArgumentNotValidException ex) {

        String msg = ex.getBindingResult().getFieldErrors().stream()
                .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
                .collect(Collectors.joining("; "));

        log.warn("Validation error: {}", msg);
        return ResponseEntity
                .status(HttpStatus.BAD_REQUEST)
                .body(AccountEnquiryResponse.error("INVALID REQUEST: " + msg));
    }

    /** Malformed request body (unparseable JSON). Returns HTTP 400. */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<AccountEnquiryResponse> handleNotReadable(
            HttpMessageNotReadableException ex) {
        log.warn("Unreadable request body: {}", ex.getMessage());
        return ResponseEntity
                .status(HttpStatus.BAD_REQUEST)
                .body(AccountEnquiryResponse.error("INVALID REQUEST: " + ex.getMessage()));
    }

    /** Path-variable type mismatch (e.g. non-numeric account ID). Returns HTTP 400. */
    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
    public ResponseEntity<AccountEnquiryResponse> handleTypeMismatch(
            MethodArgumentTypeMismatchException ex) {
        String msg = ex.getName() + ": invalid value '" + ex.getValue() + "'";
        log.warn("Type mismatch: {}", msg);
        return ResponseEntity
                .status(HttpStatus.BAD_REQUEST)
                .body(AccountEnquiryResponse.error("INVALID REQUEST: " + msg));
    }

    /**
     * Unexpected errors — replaces PERFORM 9000-ERROR + 8000-TERMINATION.
     * Returns HTTP 500.
     */
    @ExceptionHandler(Exception.class)
    public ResponseEntity<AccountEnquiryResponse> handleUnexpected(Exception ex) {
        log.error("Unexpected error during account enquiry", ex);
        return ResponseEntity
                .status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(AccountEnquiryResponse.error(
                        "INTERNAL ERROR: " + ex.getMessage()));
    }
}
